SELECT 
FROM task
WHERE id = #{id}
  AND user_id = #{userId}

SELECT 
FROM task
WHERE user_id = #{userId}

  AND template_id = #{templateId}


  AND (created_at < #{cursorCreatedAt}
    OR (created_at = #{cursorCreatedAt} AND id < #{cursorId}))

ORDER BY created_at DESC, id DESC
LIMIT #{limit}
